INSERT INTO pages (slug, title, content) VALUES
  ('terms', 'İstifadə Şərtləri', '<p>Yük.Birlikdə.biz yalnız müştərilərlə yükdaşıma sürücülərini bir araya gətirən rəqəmsal elan və təklif platformasıdır. Platforma yük daşımır, qiymət müəyyən etmir, komissiya hesablamır və tərəflər arasındakı razılaşmanın iştirakçısı deyil.</p>'),
  ('privacy', 'Məxfilik Siyasəti', '<p>Platforma yalnız ad, soyad və telefon nömrəsi kimi minimum məlumatları toplayır. Profil şəkli könüllüdür. Məlumatlarınız üçüncü tərəflərlə paylaşılmır.</p>'),
  ('about', 'Haqqımızda', '<p>Yük.Birlikdə.biz müştəriləri və yükdaşıma sürücülərini birləşdirən rəqəmsal platformadır.</p>'),
  ('faq', 'Tez-tez verilən suallar', '<p>Tezliklə əlavə olunacaq.</p>'),
